#include "postquantiquecoin/crypto/PQAlgorithmRegistry.h"
#include <map>
namespace pqc { namespace { struct Info{size_t pk,sk,sig,ct; bool prod;}; const std::map<std::string,Info>& M(){ static std::map<std::string,Info> m{{"ML-DSA-44",{1312,2560,2420,0,true}},{"ML-DSA-65",{1952,4032,3309,0,true}},{"ML-DSA-87",{2592,4896,4627,0,true}},{"ML-KEM-512",{800,1632,0,768,true}},{"ML-KEM-768",{1184,2400,0,1088,true}},{"ML-KEM-1024",{1568,3168,0,1568,true}},{"SLH-DSA",{32,64,7856,0,false}}}; return m;} } bool PQAlgorithmRegistry::IsSignatureAlgorithmAllowed(const std::string& a){ return a.rfind("ML-DSA",0)==0||a.rfind("SLH-DSA",0)==0; } bool PQAlgorithmRegistry::IsKemAlgorithmAllowed(const std::string& a){ return a.rfind("ML-KEM",0)==0; } size_t PQAlgorithmRegistry::GetExpectedPublicKeySize(const std::string& a){ auto it=M().find(a); return it==M().end()?0:it->second.pk;} size_t PQAlgorithmRegistry::GetExpectedPrivateKeySize(const std::string& a){ auto it=M().find(a); return it==M().end()?0:it->second.sk;} size_t PQAlgorithmRegistry::GetExpectedSignatureSize(const std::string& a){ auto it=M().find(a); return it==M().end()?0:it->second.sig;} size_t PQAlgorithmRegistry::GetExpectedCiphertextSize(const std::string& a){ auto it=M().find(a); return it==M().end()?0:it->second.ct;} bool PQAlgorithmRegistry::IsProductionAllowed(const std::string& a){ auto it=M().find(a); return it!=M().end()&&it->second.prod;} }
